        await using(var db=new FirmenDbContext(options)){await db.Database.EnsureCreatedAsync();db.Benutzer.Add(new(){Id="u",Login="muster",Anzeigename="Muster",PasswortHash=Secret()});db.Kontakte.AddRange(new KontaktDatensatz{Id="fa",Name="Fennring Büro",Suchname="fennring"},new KontaktDatensatz{Id="fb",Name="Vertrauliche Musterfirma",Suchname="vertrauliche musterfirma"});db.Kategorien.Add(new(){Id="kat",Name="Vertrag",Suchname="vertrag"});db.Akten.AddRange(new AkteDatensatz{Id="a",Titel="Erlaubt",Suchtext="erlaubt",FirmaId="fa",KategorieId="kat"},new AkteDatensatz{Id="b",Titel="Vertraulich",Suchtext="vertraulich",FirmaId="fb",KategorieId="kat"});db.Dokumente.Add(new(){Id="docb",Titel="Vertraulich",Dateiname="Brief.txt",StorageKey=new string('a',32),Hash=new string('A',64),Groesse=8,Inhaltstyp="text/plain"});db.Dokumentzuordnungen.Add(new(){DokumentId="docb",AkteId="b"});db.Freigaben.Add(new(){BenutzerId="u",KontaktId="fa"});await db.SaveChangesAsync();}
        var accessor=new HttpContextAccessor{HttpContext=new DefaultHttpContext()};accessor.HttpContext.User=new(new ClaimsIdentity([new(ClaimTypes.NameIdentifier,"u"),new(ClaimTypes.Role,"Mitarbeiter")],"test"));var rights=new Ressourcenbereich(accessor,new(true,null,null));
        await using(var db=new FirmenDbContext(options,rights)){Assert.True(db.RechteFiltern);Assert.Equal("fa",(await db.Kontakte.SingleAsync()).Id);Assert.Equal("a",(await db.Akten.SingleAsync()).Id);Assert.Empty(await db.Dokumente.ToArrayAsync());Assert.Empty(await db.Dokumentzuordnungen.ToArrayAsync());Assert.Empty(await new FirmenDaten(db).Suchen("Vertraulich",new LokalerDemozugriff(),new Arbeitsmodule()));await Assert.ThrowsAsync<Arbeitsfehler>(()=>new FirmenDaten(db).AkteStatus("b",new("Erledigt",1)));}
        accessor.HttpContext.User=new(new ClaimsIdentity([new(ClaimTypes.NameIdentifier,"u"),new(ClaimTypes.Role,"Administrator")],"test"));await using(var db=new FirmenDbContext(options,rights))Assert.Equal(2,await db.Kontakte.CountAsync());
    }

    [Fact] public async Task RechnungsrechtBehaeltZahlungsbetragTrotzGeschuetztemDrittzahler(){
        await using var cn=new SqliteConnection("Data Source=:memory:");await cn.OpenAsync();var options=new DbContextOptionsBuilder<FirmenDbContext>().UseSqlite(cn).Options;var rid=Guid.NewGuid().ToString("N");var pid=Guid.NewGuid().ToString("N");
        await using(var db=new FirmenDbContext(options)){await db.Database.EnsureCreatedAsync();db.Benutzer.Add(new(){Id="u",Login="muster",Anzeigename="Muster",PasswortHash=Secret()});foreach(var id in new[]{"kunde","eigen","dritt"})db.Kontakte.Add(new(){Id=id,Name="Muster "+id,Suchname=id});db.Kategorien.Add(new(){Id="k",Name="Vertrag",Suchname="vertrag"});db.Akten.Add(new(){Id="a",Titel="Musterakte",Suchtext="musterakte",FirmaId="kunde",KategorieId="k"});db.Freigaben.AddRange(new Ressourcenfreigabe{BenutzerId="u",KontaktId="kunde"},new Ressourcenfreigabe{BenutzerId="u",KontaktId="eigen"});db.Rechnungen.Add(new(){Id=rid,AkteId="a",AusstellerId="eigen",EmpfaengerId="kunde",Nummer="RE-2026-441",Datum=new(2026,10,19),Betrag=100,Richtung="Ausgang",Zahlungsstatus="Teilweise bezahlt"});db.Zahlungen.Add(new(){Id=pid,ZahlerId="dritt",EmpfaengerId="eigen",Datum=new(2026,10,19),Betrag=30});db.Zahlungsbestaetigungen.Add(new(){ZahlungId=pid,Benutzer="Muster",Zeitpunkt=DateTimeOffset.UtcNow});db.Zahlungszuordnungen.Add(new(){RechnungId=rid,ZahlungId=pid,Betrag=30,Benutzer="Muster",Zeitpunkt=DateTimeOffset.UtcNow});await db.SaveChangesAsync();}
        var accessor=new HttpContextAccessor{HttpContext=new DefaultHttpContext()};accessor.HttpContext.User=new(new ClaimsIdentity([new(ClaimTypes.NameIdentifier,"u"),new(ClaimTypes.Role,"Mitarbeiter")],"test"));await using var check=new FirmenDbContext(options,new Ressourcenbereich(accessor,new(true,null,null)));var view=await new FirmenDaten(check).Rechnungsuebersicht(0,new LokalerDemozugriff());var invoice=Assert.Single(view.Rechnungen);Assert.Contains("30,00",invoice.BestaetigtZugeordnet);Assert.Contains("70,00",invoice.OffenerBetrag);Assert.Single(invoice.Zahlungen);Assert.DoesNotContain("Muster dritt",invoice.Zahlungen.Single().Zahler);Assert.False(await check.Kontakte.AnyAsync(k=>k.Id=="dritt"));
    }
    [Fact] public async Task BestandsabgleichErkenntHarteAbbruchresteOhneLoeschung(){
        var root=Root();var f=new LokaleDokumentdateien(root);await f.StartAsync(default);await using var cn=new SqliteConnection("Data Source=:memory:");await cn.OpenAsync();await using var db=new FirmenDbContext(new DbContextOptionsBuilder<FirmenDbContext>().UseSqlite(cn).Options);await db.Database.EnsureCreatedAsync();
        var bytes=System.Text.Encoding.UTF8.GetBytes("Musterbrief");var key=Guid.NewGuid().ToString("N");await f.Speichern(key,bytes,default);db.Dokumente.Add(new(){Id="d",Titel="Brief",Dateiname="Brief.txt",StorageKey=key,Hash=Hash(bytes),Groesse=bytes.Length});await db.SaveChangesAsync();Assert.True((await Dokumentbestand.Pruefen(db,root)).Konsistent);
        await File.WriteAllBytesAsync(Path.Combine(root,key+".bin"),[42]);await f.Speichern(Guid.NewGuid().ToString("N"),bytes,default);await File.WriteAllBytesAsync(Path.Combine(root,Guid.NewGuid().ToString("N")+".pending"),[1]);var r=await Dokumentbestand.Pruefen(db,root);Assert.Equal(1,r.Abweichend);Assert.Equal(1,r.Verwaist);Assert.Equal(1,r.Temporaer);Assert.Equal(3,Directory.GetFiles(root).Length);
        await f.Entfernen(key,default);Assert.Equal(1,(await Dokumentbestand.Pruefen(db,root)).Fehlend);
    }
