    private sealed class CrashChildAttribute:FactAttribute{public CrashChildAttribute(){if(Environment.GetEnvironmentVariable("FZ_CRASH_CHILD")==null)Skip="Isolated process termination helper.";}}
    [CrashChild] public async Task CrashChild(){
        var root=Environment.GetEnvironmentVariable("FZ_CRASH_CHILD")!;var phase=Environment.GetEnvironmentVariable("FZ_CRASH_PHASE");var key=Guid.NewGuid().ToString("N");
        if(phase=="writing"){
            await using var file=new FileStream(Path.Combine(root,key+".pending"),FileMode.CreateNew,FileAccess.Write,FileShare.Read);await file.WriteAsync(new byte[4096]);await file.FlushAsync();await File.WriteAllTextAsync(Path.Combine(root,"ready"),"ready");await Task.Delay(Timeout.Infinite);
        }else{await new LokaleDokumentdateien(root).Speichern(key,[1,2,3],default);await File.WriteAllTextAsync(Path.Combine(root,"ready"),"ready");await Task.Delay(Timeout.Infinite);}
    }
    [Theory][InlineData("writing")][InlineData("after-storage")]public async Task HarterProzessabbruchWirdBeimNeustartErkannt(string phase){
        var root=Root();var storage=new LokaleDokumentdateien(root);await storage.StartAsync(default);var key=Guid.NewGuid().ToString("N");await storage.Speichern(key,[42],default);
        await using var cn=new SqliteConnection("Data Source=:memory:");await cn.OpenAsync();await using var db=new FirmenDbContext(new DbContextOptionsBuilder<FirmenDbContext>().UseSqlite(cn).Options);await db.Database.EnsureCreatedAsync();db.Dokumente.Add(new(){Id="original",Titel="Gültig",Dateiname="Original.txt",StorageKey=key,Hash=Hash([42]),Groesse=1});await db.SaveChangesAsync();
        var start=new System.Diagnostics.ProcessStartInfo("dotnet"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};foreach(var arg in new[]{"test",Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,"../../../Betriebsplattform.Rechnungen.Tests.csproj")),"--no-build","--no-restore","--filter","FullyQualifiedName~Mvp02BSicherheitTests.CrashChild","--verbosity","quiet"})start.ArgumentList.Add(arg);start.Environment["FZ_CRASH_CHILD"]=root;start.Environment["FZ_CRASH_PHASE"]=phase;
        using var process=System.Diagnostics.Process.Start(start)!;var stdout=process.StandardOutput.ReadToEndAsync();var stderr=process.StandardError.ReadToEndAsync();
        try{using var deadline=new CancellationTokenSource(TimeSpan.FromSeconds(30));while(!File.Exists(Path.Combine(root,"ready"))){if(process.HasExited)throw new InvalidOperationException("Isolierter Testprozess vor Bereitschaft beendet.");await Task.Delay(100,deadline.Token);}process.Kill(entireProcessTree:true);await process.WaitForExitAsync();}
        finally{if(!process.HasExited){process.Kill(entireProcessTree:true);await process.WaitForExitAsync();}}
        await stdout;await stderr;await new LokaleDokumentdateien(root).StartAsync(default);var report=await Dokumentbestand.Pruefen(db,root);Assert.False(report.Konsistent);if(phase=="writing")Assert.True(report.Temporaer>=1);else Assert.Equal(1,report.Verwaist);Assert.Equal(new byte[]{42},await storage.Lesen(key,default));Assert.Equal(1,await db.Dokumente.CountAsync());
    }
