        async Task<(Microsoft.AspNetCore.Builder.WebApplication App,Uri Url)> Start(string connection,string root){var app=ApiAnwendung.Erstellen(["--FirmenZentrale:Persistence:Provider=PostgreSql","--FirmenZentrale:Persistence:DocumentRoot="+root,"--ConnectionStrings:FirmenZentrale="+connection,"--FirmenZentrale:Security:Enabled=true"],0,testZertifikat:cert);try{await app.StartAsync();}catch{await app.DisposeAsync();throw;}var server=Microsoft.Extensions.DependencyInjection.ServiceProviderServiceExtensions.GetRequiredService<Microsoft.AspNetCore.Hosting.Server.IServer>(app.Services);return(app,new Uri(server.Features.Get<Microsoft.AspNetCore.Hosting.Server.Features.IServerAddressesFeature>()!.Addresses.Single()));}
