            var psi=new System.Diagnostics.ProcessStartInfo("dotnet"){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=Path.GetDirectoryName(published)!,RedirectStandardOutput=true,RedirectStandardError=true};psi.ArgumentList.Add(published);
            psi.Environment["DOTNET_ENVIRONMENT"]="Production";psi.Environment["ASPNETCORE_ENVIRONMENT"]="Production";psi.Environment["FirmenZentrale__Persistence__Provider"]="PostgreSql";psi.Environment["FirmenZentrale__Persistence__DocumentRoot"]=restoreRoot;psi.Environment["ConnectionStrings__FirmenZentrale"]=restoredApp.ConnectionString;psi.Environment["FirmenZentrale__Security__Enabled"]="true";psi.Environment["FirmenZentrale__Security__CertificatePath"]=certificatePath;psi.Environment["FirmenZentrale__Security__CertificatePassword"]=certificateSecret;psi.Environment["FirmenZentrale__Network__Port"]=port.ToString();
            using var process=System.Diagnostics.Process.Start(psi)!;var stdout=process.StandardOutput.ReadToEndAsync();var stderr=process.StandardError.ReadToEndAsync();
